local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[404805]=b({e[24034],404805,3,54,260,"「あの、私の役は『幽霊の花嫁』で……。それで、もし良かったら、台詞の練習に付き合って欲しいの。　じ、じゃあ、始めるの……『ヒ、ヒッヒッヒ、ここまで来たからには、私の魂の、は、半身として残ってもらいます！』」",200048,2,"deco/character/senchuanlingzi_WS",false,false,false,false,false,false,false,"1",false,false,"-150,0,1","240,-140,1","-150,0,1","-280,0,1","-150,0,1",2081,842,393,596,473,2868,2869,596,538,2868,false,1,5437,5000,3086,2651,8000,15666,14166,12666,15000,8000,8000,"senchuanlingzi_ws"},h)g[404806]=b({e[17044],404806,4,96,261,"「雪、なの……。\nごめんなさい……こんな日に呼び出して。髪に雪が積もってるし、手もきっと、冷たくなってるの。\nじ、実は今日、花子が、「鹿の角をつけて、大切な人と会えば、その人は鹿の角を持つ精霊の加護を受けられる」って言ったの……\nそ、それで……私、わがままなの……？」",200048,2,"deco/character/senchuanlingzi_sd",false,false,false,false,false,false,false,"",0,1,1959,5000,986,2117,5333,10233,12699,8366,10000,8000,5333,"senchuanlingzi_sd"},h)g[404901]=b({e[33044],404901,false,122,262,false,200049,false,"deco/character/longchuanxiayan",302002,60,false,false,false,false,-85,"0.949999988079071",false,false,false,false,false,false,false,"0,470,0.94","-60,30,0.95","0,30,0.95","0,0,0.95","0,0,0.95","0,0,0.95","-70,30,0.95","0,30,0.95","0,0,0.95",0,false,false,false,false,false,false,false,false,false,false,false,false,"longchuanxiayan"},h)g[404902]=b({e[11044],404902,1,4,263,"「そういやさ、さっきの試合、あれだけの歓声の中で、お前の声だけはすっごくハッキリ聞こえたんだ。\nだから、絶対このシュートを決めてやる！ って思ったんだよな、ハハッ。」",200049,1,"deco/character/longchuanxiayan_0",302002,60,0,false,false,false,false,false,false,false,false,false,false,false,false,"longchuanxiayan_0"},h)g[404903]=b({e[12044],404903,13,87,264,"「湯口の近くはやっぱり水温が高いなあ、いきなりこっちの方に入るのはちょっと無茶かも、ははっ！　浅いところで体を慣らしてから、こっちに来ればいいって。……ふう～。試合後の温泉ってサイッコー！」",200049,2,"deco/character/longchuanxiayan_WQ",false,false,1,0,false,false,false,false,false,false,false,false,false,false,false,false,"longchuanxiayan_wq"},h)g[404904]=b({e[24044],404904,6,70,265,"「謎解き提灯……？　いや、遠慮しとくわ。俺こういうやつマジで苦手なんだよ。でも賞品が欲しいってことなら、なぞなぞを選ばなくてもいいんじゃないか？　獅子舞ならぬ龍舞大会なら任しとけ、体力なら絶対負けないからな！」",200049,2,"deco/character/longchuanxiayan_CJ",false,false,false,false,false,false,false,"1",false,"-20,920,1","-20,920,1","120,920,0.91","-20,920,1","-20,920,1","-100,920,1",0,false,false,false,false,false,false,false,false,false,false,false,false,"longchuanxiayan_cj"},h)g[404905]=b({e[9044],404905,20,89,266,"「ひゅーっ！\nおっ、お前か！ 俺、スケートボードできるようになったんだ！\n案外簡単だし、お前もやってみないか？\n今日は一日暇だし、スケボーじゃなくても、何でも付き合うぜ。」",200049,2,"deco/character/longchuanxiayan_yh",0,false,false,false,false,false,false,false,false,false,false,false,false,"longchuanxiayan_yh"},h)g[405001]=b({e[46057],405001,false,123,267,false,200050,false,"deco/character/akagi",302002,60,false,false,false,false,-85,"1",false,false,false,false,false,false,false,"40,310,1",false,false,false,false,false,false,false,false,false,false,1887,827,417,1436,721,1122,2880,1436,721,1122,1075,"chimumao"},h)g[405002]=b({e[11034],405002,1,4,268,false,200050,1,"deco/character/akagi_0",302002,60,1892,846,417,1226,626,1522,2636,1226,626,1522,1189,false,false,false,false,false,false,false,false,false,false,false,false,"chimumao_0"},h)g[405003]=b({e[9034],405003,999,124,269,"天下無双・降龍威光",200050,3,"deco/character/akagi_SP",1959,815,402,416,698,3326,3100,628,698,2902,1078,false,false,false,false,false,false,false,false,false,false,false,false,"chimumao_1"},h)g[405004]=b({e[9044],405004,998,125,270,"「その殺意の源は、つまるところ死を恐れる心さ……！」",200050,3,"deco/character/akagi_SP2",0,1,4400,5000,2356,2063,8000,8000,8000,8000,13000,8000,8000,"chimumao_2"},h)g[405101]=b({e[46057],405101,false,126,271,false,200051,false,"deco/character/washizu",302002,60,1,false,false,false,-29,"1",false,false,false,false,false,false,false,"0,180,1",false,false,false,false,false,false,false,false,false,false,1909,828,397,1421,638,1232,2826,1421,638,1232,1149,"jiuchaoyan"},h)g[405102]=b({e[14034],405102,1,4,272,false,200051,1,"deco/character/washizu_0",302002,60,false,1,1,1935,834,412,1109,777,1996,2818,1109,777,1996,1